{"mainFeatures":["CSV 파일 스트림 읽기 (청크 단위)","NaN 값 처리 (drop/fill/interpolate 전략)","특수 문자 필터링 (정규식 기반)","진행률 추적 (콜백 지원)","병렬 처리 (concurrent.futures)"],"components":[{"name":"loadData","description":"CSV 파일을 비동기 스트림으로 읽어옵니다","signature":"(filePath: string, options?: LoadOptions) => AsyncGenerator<DataFrame>"},{"name":"cleanText","description":"텍스트에서 특수문자를 제거하고 공백을 정규화합니다","signature":"(text: string, options?: CleanOptions) => string"},{"name":"handleNaN","description":"NaN 값 처리 전략을 적용합니다","signature":"(df: DataFrame, strategy: NaNStrategy) => DataFrame"},{"name":"processParallel","description":"여러 청크를 병렬로 처리합니다","signature":"(chunks: DataFrame[], workers: number) => Promise<DataFrame[]>"}],"io":{"inputs":[{"name":"filePath","type":"string","description":"CSV 파일의 절대 경로 또는 상대 경로"},{"name":"options","type":"ProcessOptions","description":"처리 옵션 (chunkSize, nanStrategy, encoding, onProgress 등)"}],"outputs":[{"name":"result","type":"AsyncGenerator<ProcessedData>","description":"처리된 데이터 청크의 스트림"}]},"examples":["// 기본 사용법
const processor = new CSVDataProcessor();
for await (const chunk of processor.loadData('data.csv')) {
  console.log(`Processed ${chunk.rowCount} rows`);
}","// 고급 옵션 사용
const processor = new CSVDataProcessor({
  chunkSize: 10000,
  nanStrategy: 'interpolate',
  encoding: 'utf-8',
  parallel: true,
  workers: 4
});

const result = await processor.process('large-file.csv', {
  filters: ['trim', 'lowercase', 'remove-special-chars'],
  onProgress: (percent) => console.log(`Progress: ${percent}%`)
});"]}
